<?php declare(strict_types=1); $this->layout('layouts/default',['title'=>$title,'currentPage'=>'media']); ?>
<section class="studio-page"><header class="studio-page-heading"><div><p class="studio-eyebrow">CONTEÚDO</p><h2>Mídia</h2><p>Biblioteca segura de imagens do Moves.</p></div></header><form class="studio-form-card" method="post" enctype="multipart/form-data"><?= $this->csrf() ?><input type="hidden" name="action" value="upload"><div class="studio-field"><label for="image">Nova imagem — JPG, PNG, GIF ou WebP, até 8 MB</label><input id="image" type="file" name="image" accept="image/jpeg,image/png,image/gif,image/webp" required></div><button>Enviar imagem</button></form><form class="studio-filter-bar studio-single-filter" method="get"><label><span>Busca</span><input name="q" value="<?= $this->e($search) ?>" placeholder="Nome do arquivo"></label><button>Buscar</button></form><div class="studio-media-grid"><?php if($files===[]):?><p class="studio-panel studio-empty">Nenhuma imagem enviada.</p><?php endif;?><?php foreach($files as $file):?><article class="studio-panel"><img src="/admin/media/file/<?= $this->e((string)$file['id']) ?>" alt=""><h3><?= $this->e($file['name']) ?></h3><p><?= $this->e((string)$file['width']) ?> × <?= $this->e((string)$file['height']) ?> · <?= $this->e(number_format(((int)$file['size'])/1024,1,',','.')) ?> KB</p><form method="post"><?= $this->csrf() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= $this->e((string)$file['id']) ?>"><button class="studio-danger-button" onclick="return confirm('Excluir esta imagem?')">Excluir</button></form></article><?php endforeach;?></div></section>
